function showDetail(id,scroll=false){el('detail').value=id;const x=byId[id];if(!x)return;const h=x.holdout;el('detailText').innerHTML=`<h3>${title(x)}</h3><p>第一袋：${DATA.names[x.p1]}；第二袋：${DATA.names[x.p2]}。首杆打点 ${tip(x)}；第二杆 ${x.secondControl.v}m/s，${tip(x.secondControl)}。</p><p>留出两杆 <b>${ratio(h)}（${pct(h.rate)}）</b>；首杆有效 ${h.firstPass}/${h.n}，其中执行第二杆 ${h.secondExecuted} 次。第二杆零误差重放通过 ${h.zeroErrorSecondPass} 次，误差意外挽救 ${h.noiseRescued} 次。</p>${bars(h)}<p class="note">首杆拒绝原因：${Object.entries(x.firstReasons).map(([k,v])=>k+' '+v).join('；')||'无'}。第二杆拒绝原因：${Object.entries(x.secondReasons).map(([k,v])=>k+' '+v).join('；')||'无'}。同次存在多种原因时按固定优先级归类。</p><p class="note">辅助读数：仅检查指定袋进球且母球未落袋，首杆为 ${h.firstPotSafe}/${h.n}，第二杆为 ${h.secondPotSafe}/${h.secondExecuted}（只统计实际执行）。这不计其他资格条件，也不用于排名；不能推算宽松规则下的完整两杆率。</p>`;el('detailRoute').src=x.routeImage;el('detailStops').src=x.stopsImage;el('routeLink').href=x.routeImage;el('stopsLink').href=x.stopsImage;const yn=b=>`<span class="${b?'positive':'negative'}">${b?'通过':'失败'}</span>`;el('axes').innerHTML='<thead><tr><th>探针</th><th>零误差</th><th>速度 − / ＋</th><th>方向 − / ＋</th><th>横打点 − / ＋</th><th>纵打点 − / ＋</th></tr></thead><tbody>'+[['第一杆',x.firstAxes],['第二杆',x.secondAxes]].map(([label,a])=>`<tr><th>${label}</th><td>${yn(a[0])}</td>${[1,3,5,7].map(i=>`<td>${yn(a[i])} / ${yn(a[i+1])}</td>`).join('')}</tr>`).join('')+'</tbody>';if(scroll)el('detailSection').scrollIntoView({behavior:'auto',block:'start'})}
function matrix(){const order=el('matrixOrder').value;let html='<thead><tr><th>第一杆 ↓ / 第二杆 →</th>'+DATA.short.map(x=>`<th>${x}</th>`).join('')+'</tr></thead><tbody>';for(let p1=0;p1<6;p1++){html+=`<tr><th>${DATA.short[p1]}</th>`;for(let p2=0;p2<6;p2++){const m=DATA.matrix.find(x=>x.order===order&&x.p1===p1&&x.p2===p2),c=m.id?byId[m.id]:null;html+=`<td><button class="${c?'tested':'excluded'}" data-pair="${p1},${p2}" aria-label="${order} ${DATA.names[p1]}到${DATA.names[p2]} ${m.status}">${c?ratio(c.holdout)+'<br>'+c.styleLabel:m.status}</button></td>`}html+='</tr>'}el('matrix').innerHTML=html+'</tbody>';el('matrixInfo').textContent='点击一个组合查看筛选原因。';el('matrix').querySelectorAll('button').forEach(b=>b.onclick=()=>{const [p1,p2]=b.dataset.pair.split(',').map(Number),m=DATA.matrix.find(x=>x.order===order&&x.p1===p1&&x.p2===p2);el('matrixInfo').textContent=`${order[0]}→${order[1]}，${DATA.names[p1]}→${DATA.names[p2]}：${m.status}。首杆切角 ${m.cutDegrees.toFixed(1)}°，${m.firstSlots} 个首杆槽位中 ${m.firstNominalPass} 个名义通过；${m.nominalStrategies} 个名义两杆见证，${m.assessed} 个进入复验。`;if(m.id)showDetail(m.id)})}
['left','right','detail'].forEach(k=>opts(el(k)));el('left').value=DATA.winners.AB||DATA.items[0]?.id||'';el('right').value=DATA.winners.BA||DATA.items[0]?.id||'';['left','right'].forEach(k=>{el(k).onchange=()=>compare(k);compare(k)});el('detail').onchange=()=>showDetail(el('detail').value);if(DATA.items.length)showDetail(el('left').value);el('matrixOrder').onchange=matrix;matrix();el('allRows').innerHTML=DATA.items.map(x=>`<tr><td><button data-id="${x.id}">${x.order[0]}→${x.order[1]} ${DATA.short[x.p1]}→${DATA.short[x.p2]}</button></td><td>${x.styleLabel}<br>${x.v}m/s</td><td>${x.secondControl.v}m/s<br>Y ${num(x.secondControl.sy)}</td><td>${ratio(x.design)}</td><td>${ratio(x.holdout)}<br>${pct(x.holdout.rate)}</td><td>${x.holdout.firstPass}/${x.holdout.n}</td><td>${x.holdout.firstPass?x.holdout.complete+'/'+x.holdout.firstPass:'未进入'}</td></tr>`).join('');el('allRows').querySelectorAll('button').forEach(b=>b.onclick=()=>showDetail(b.dataset.id,true));const wa=byId[DATA.winners.AB],wb=byId[DATA.winners.BA];el('orderConclusion').textContent=wa&&wb?`设计集预选方案在留出集：A→B ${ratio(wa.holdout)}，B→A ${ratio(wb.holdout)}。这是该球形下有限候选与固定第二杆策略的比较，不证明某个顺序普遍更好。`:'某种顺序在本轮有限搜索中未找到名义两杆见证；不能据此宣称物理不可行。';
